from collections import deque
def comps(g):
    H,W=len(g),len(g[0]); lab=[[-1]*W for _ in range(H)]; cs=[]
    for i in range(H):
        for j in range(W):
            if g[i][j]==1 and lab[i][j]<0:
                c=[]; dq=deque([(i,j)]); lab[i][j]=len(cs)
                while dq:
                    a,b=dq.popleft(); c.append((a,b))
                    for da,db in ((1,0),(-1,0),(0,1),(0,-1)):
                        x,y=a+da,b+db
                        if 0<=x<H and 0<=y<W and g[x][y]==1 and lab[x][y]<0:
                            lab[x][y]=len(cs); dq.append((x,y))
                cs.append(c)
    return cs
