    H,W=len(g),len(g[0]); seen=[[False]*W for _ in range(H)]; dq=deque()
    for i,j in ((0,0),(0,W-1),(H-1,0),(H-1,W-1)):
        if g[i][j]==1 and not seen[i][j]: seen[i][j]=True; dq.append((i,j))
    while dq:
        a,b=dq.popleft()
        for da,db in ((1,0),(-1,0),(0,1),(0,-1)):
            x,y=a+da,b+db
            if 0<=x<H and 0<=y<W and g[x][y]==1 and not seen[x][y]:
                seen[x][y]=True; dq.append((x,y))
    return seen
