def hyp(g, mode):
    p4=set(pos4(g))
    rows={}; cols={}
    for i,j in p4: rows.setdefault(i,[]).append(j); cols.setdefault(j,[]).append(i)
    for d in (rows,cols):
        for k in d: d[k].sort()
    out=[]
    for i in range(len(g)):
        row=[]
        for j in range(len(g[0])):
            v=g[i][j]
            if v==4: row.append(4); continue
            rb=False
            rs=rows.get(i,[])
            if rs:
                lo=[x for x in rs if x<j]; hi=[x for x in rs if x>j]
                rb=bool(lo and hi)
            cb=False
            cs=cols.get(j,[])
            if cs:
                lo=[x for x in cs if x<i]; hi=[x for x in cs if x>i]
                cb=bool(lo and hi)
            f = rb and cb if mode=='and' else (rb or cb)
            row.append(3 if f else v)
        out.append(row)
    return out
